const r = await tools.exec_command({cmd:`python3 - <<'PY'
from pathlib import Path
import subprocess
path = Path("src/mcp-apps/_shared/host.test.tsx")
original = path.read_text()
assert original.endswith("});\\n")
extra = r'''
	it("keeps an app-initiated result when originating host info arrives late", async () => {
		const compatParent: CompatParent = Object.assign(new EventTarget(), {
			location: { origin: "https://chatgpt.com" },
		});
		Object.defineProperty(window, "parent", {
			configurable: true,
			value: compatParent,
		});
		bridge.callServerTool.mockImplementation(
			async ({ name, arguments: args }) => {
				if (name === "resolve_lobu_approval") {
					return {
						isError: false,
						structuredContent: { title: "Approved result" },
						_meta: {
							"lobu/mcp-app-snapshot-capability": "approved-result-token",
						},
					};
				}
				if (
					name === "restore_lobu_app_result" &&
					args.tool_call_id === "late-originating-card"
				) {
					return {
						isError: false,
						structuredContent: {
							found: true,
							tool_name: "render_lobu_view",
							data: { title: "Pending approval" },
							view_state: {},
						},
					};
				}
				return {
					isError: false,
					structuredContent: { found: false, view_state: {} },
				};
			},
		);

		const { Provider, useMcpApp } = await import("./host");
		function Probe() {
			const { callTool, data } = useMcpApp<{ title: string }>();
			return (
				<>
					<span>{data?.title ?? "No result"}</span>
					<button
						type="button"
						onClick={() => void callTool("resolve_lobu_approval", {})}
					>
						Approve
					</button>
				</>
			);
		}
		render(
			<Provider devMock={{ title: "Development result" }}>
				<Probe />
			</Provider>,
		);
		await waitFor(() => expect(bridge.connect).toHaveBeenCalledTimes(1));
		act(() => {
			for (const handler of bridge.listeners.get("toolresult") ?? []) {
				handler({
					structuredContent: { title: "Pending approval" },
					_meta: {
						"lobu/mcp-app-snapshot-capability": "pending-result-token",
					},
				});
			}
		});
		expect(await screen.findByText("Pending approval")).toBeInTheDocument();

		fireEvent.click(screen.getByRole("button", { name: "Approve" }));
		expect(await screen.findByText("Approved result")).toBeInTheDocument();

		bridge.hostContext = {
			toolInfo: {
				id: "late-originating-card",
				tool: { name: "render_lobu_view" },
			},
		};
		act(() => {
			for (const handler of bridge.listeners.get("hostcontextchanged") ?? []) {
				handler({ theme: "light" });
			}
		});

		await new Promise((resolve) => setTimeout(resolve, 20));
		expect(screen.getByText("Approved result")).toBeInTheDocument();
		expect(screen.queryByText("Pending approval")).not.toBeInTheDocument();
	});
