				) {
					return {
						isError: false,
						structuredContent: {
							found: true,
							tool_name: "query_sdk",
							data: { title: "Stale outer card" },
							view_state: {},
						},
					};
				}
				return {
					isError: false,
					structuredContent: { found: false, view_state: {} },
				};
			},
		);

