											"stale-outer-token",
									},
								},
							},
						},
					},
				}),
			);
		});

		await new Promise((resolve) => setTimeout(resolve, 20));
		expect(screen.getByText("Current inner card")).toBeInTheDocument();
		expect(screen.queryByText("Stale outer card")).not.toBeInTheDocument();
	});
'''
